CREATE OR REPLACE FUNCTION public.fn_get_active_family_contracts(p_tenant_id uuid, p_branch_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(id uuid, tenant_id uuid, branch_id uuid, application_id uuid, child_id uuid, parent_name character varying, parent_email character varying, schedule_type character varying, billing_cycle character varying, base_rate numeric, discount_percent numeric, effective_rate numeric, deposit_held numeric, status character varying, start_date date, end_date date, auto_invoice boolean, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE sql  STABLE AS $function$     SELECT          id, tenant_id, branch_id, application_id,         child_id, parent_name, parent_email,         schedule_type, billing_cycle,         base_rate, discount_percent, effective_rate,         deposit_held, status, start_date, end_date,         auto_invoice, created_at, updated_at     FROM family_billing_contracts     WHERE tenant_id = p_tenant_id       AND (p_branch_id IS NULL OR branch_id = p_branch_id)     ORDER BY created_at DESC; $function$ ;
